// Node 2: validate the uploaded screenshot. Never throws; always returns a result.
const MAX_BYTES = 3000000; // ~3 MB raw -> ~4 MB Base64 (Groq's limit for Base64 images)
const item = $input.first();
const json = item.json || {};
const binary = item.binary || {};
const keys = Object.keys(binary);
const errors = [];
let filename = '';
let mime = '';
let size = 0;
let file = null;

if (keys.length === 0) {
  errors.push('No screenshot was uploaded. Please attach a PNG or JPG image.');
} else {
  const key = keys[0];
  file = binary[key];
  filename = file.fileName || 'screenshot';
  try {
    const buf = await this.helpers.getBinaryDataBuffer(0, key);
    size = buf.length;
    if (size === 0) {
      errors.push('The uploaded file is empty (0 bytes).');
    } else {
      const isPng = size > 8 && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47;
      const isJpg = size > 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff;
      if (isPng) mime = 'image/png';
      else if (isJpg) mime = 'image/jpeg';
      else errors.push('Unsupported file type. The file content is not a PNG or JPEG image (filename: ' + filename + ').');
      if (size > MAX_BYTES) {
        errors.push('Image is too large (' + (size / 1000000).toFixed(1) + ' MB). Please upload an image under 3 MB.');
      }
    }
  } catch (e) {
    errors.push('The uploaded file could not be read: ' + e.message);
  }
}

const valid = errors.length === 0;
const out = {
  json: {
    valid,
    errors,
    filename,
    mime,
    sizeBytes: size,
    reporterEmail: String(json['Reporter Email'] || '').trim(),
    notes: String(json['Additional Notes'] || '').trim(),
  },
};
if (valid) out.binary = { screenshot: file }; // normalise the binary key name
return [out];

// Node 5: turn the Groq response (or any failure) into a readable ticket + HTML for the Form Ending page.
const prep = $('Prepare Screenshot Data').first().json;
const res = $input.first().json;

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const redact = (s) => String(s).replace(/gsk_[A-Za-z0-9]+/g, '[redacted]').replace(/Bearer\s+\S+/gi, 'Bearer [redacted]');
const BAR = '========================================';

function fail(reason) {
  const text = BAR + '\nVISUAL BUG-TO-TICKET GENERATOR\n' + BAR + '\n\nCould not generate a bug ticket.\n\nReason:\n' + reason + '\n\n' + BAR;
  return [{ json: { ok: false, title: 'Could not generate the bug ticket', ticketText: text,
    ticketHtml: '<b>Could not generate the bug ticket.</b><br><br>' + esc(reason).replace(/\n/g, '<br>') } }];
}

// 1) Error from the LLM chain / Groq
if (res.error) {
  const m = redact(typeof res.error === 'string' ? res.error : (res.error.message || JSON.stringify(res.error))).slice(0, 400);
  let reason;
  if (/401|invalid api key|unauthor/i.test(m)) reason = 'Authentication failed. The Groq API key is missing or invalid. Check the credential in n8n.';
  else if (/429|rate limit/i.test(m)) reason = 'Groq rate limit reached. Wait a minute and try again.';
  else if (/413|too large|payload/i.test(m)) reason = 'The image is too large for Groq. Upload a smaller image.';
  else if (/404|model.*(not found|decommission|does not exist)/i.test(m)) reason = 'Model not found or retired. Check the model name in the Groq Chat Model node.';
  else if (/ENOTFOUND|ECONN|ETIMEDOUT|fetch failed|network/i.test(m)) reason = 'Could not reach the Groq API (network error). Try again.';
  else reason = 'The AI request failed: ' + m;
  return fail(reason);
}

// 2) Read the model output
let content = res.text ?? res.output ?? res.response;
if (Array.isArray(content)) content = content.map((p) => p.text || '').join('');
if (typeof content !== 'string' || content.trim() === '') {
  return fail('Groq returned an empty response. Please try again.');
}
let cleaned = content.replace(/<think>[\s\S]*?<\/think>/g, '').trim();
const first = cleaned.indexOf('{');
const last = cleaned.lastIndexOf('}');
let t;
try {
  if (first === -1 || last <= first) throw new Error('no JSON object found');
  t = JSON.parse(cleaned.slice(first, last + 1));
} catch (e) {
  return fail('The AI response was not valid JSON (' + e.message + '). Please try again.\nResponse preview: ' + redact(cleaned).slice(0, 300));
}

// 4) Build the ticket
const asText = (x, d) => (x === undefined || x === null || String(x).trim() === '' ? d : String(x).trim());
const asList = (x) => (Array.isArray(x) ? x.map((s) => String(s)) : (x ? [String(x)] : []));
const detected = t.bug_detected !== false;
const sevOk = ['Critical', 'High', 'Medium', 'Low'];
const priOk = ['P1', 'P2', 'P3', 'P4'];
const severity = detected ? (sevOk.includes(t.severity) ? t.severity : 'Not specified') : 'N/A';
const priority = detected ? (priOk.includes(t.priority) ? t.priority : 'Not specified') : 'N/A';
const steps = asList(t.steps_to_reproduce);
const limits = asList(t.limitations);

const sections = [
  ['Bug Title', asText(t.bug_title, detected ? 'Untitled visual bug' : 'No obvious visual bug detected')],
  ['Bug Category', asText(t.bug_category, detected ? 'Not specified' : 'N/A')],
  ['Severity', severity],
  ['Priority', priority],
  ['Description', asText(t.bug_description, detected ? 'Not provided' : 'No obvious visual defect was identified in this screenshot.')],
  ['Steps to Reproduce', steps.length ? steps.map((s, i) => (i + 1) + '. ' + s).join('\n') : 'Not enough information to determine steps from the screenshot alone.'],
  ['Expected Result', asText(t.expected_result, 'Not specified')],
  ['Actual Result', asText(t.actual_result, 'Not specified')],
  ['Screenshot', prep.filename],            // always from the workflow, never from the AI
  ['Reporter', prep.reporterEmail],         // always from the workflow, never from the AI
  ['AI Confidence', asText(t.ai_confidence, 'Not specified')],
  ['Recommended Fix', asText(t.recommended_fix, detected ? 'Not specified' : 'N/A')],
  ['Limitations', limits.length ? limits.map((s) => '- ' + s).join('\n') : 'None reported. Functional behaviour cannot be verified from a screenshot.'],
];

const ticketText = BAR + '\nVISUAL BUG-TO-TICKET GENERATOR\n' + BAR + '\n\n' +
  sections.map(([k, v]) => k + ':\n' + v).join('\n\n') + '\n\n' + BAR;
const ticketHtml = sections.map(([k, v]) => '<b>' + esc(k) + '</b><br>' + esc(v).replace(/\n/g, '<br>')).join('<br><br>');

return [{ json: { ok: true, title: detected ? 'Bug ticket generated' : 'No obvious visual bug detected', ticketText, ticketHtml } }];
